  ['k' => 'area', 'en' => 'Land area', 'gu' => 'જમીનનો વિસ્તાર', 'v' => 5],
  ['k' => 'unit', 'en' => 'Area unit', 'gu' => 'વિસ્તારનો એકમ', 'v' => 3, 'opts' => [[1, 'Acre', 'એકર'], [2, 'Hectare', 'હેક્ટર'], [3, 'Vigha', 'વીઘા'], [4, 'Guntha', 'ગુંઠા']]],
  ['k' => 'vg', 'en' => '1 vigha = how many guntha (your area)', 'gu' => '1 વીઘા = કેટલા ગુંઠા (તમારા વિસ્તારમાં)', 'v' => 16, 'u' => 'guntha', 'u_gu' => 'ગુંઠા'],
];
$HA = '(v.unit == 1 ? v.area * 0.40468564 : v.unit == 2 ? v.area : v.unit == 3 ? v.area * v.vg * 101.17 / 10000 : v.area * 101.17 / 10000)';
$AREA_FAQ = ['What is the size of one vigha?', 'Vigha size differs by district in Gujarat. In much of Saurashtra 1 vigha = 16 guntha (about 1,619 m²), while in other areas it can be larger. Enter the guntha per vigha used in your village. 1 acre = 40 guntha and 1 guntha = 101.17 m².',
  'એક વીઘો કેટલો હોય?', 'ગુજરાતમાં વીઘાનું માપ જિલ્લા પ્રમાણે જુદું છે. સૌરાષ્ટ્રના ઘણા ભાગમાં 1 વીઘો = 16 ગુંઠા (આશરે 1,619 ચો.મી.) છે, બીજે વધુ પણ હોય. તમારા ગામમાં ચાલતા ગુંઠા દાખલ કરો. 1 એકર = 40 ગુંઠા અને 1 ગુંઠો = 101.17 ચો.મી.'];

// Horizontal cylindrical tank: clamp dip between 0 and diameter.
$TH = 'min(max(v.dip, 0), v.dia)';
$TR = '(v.dia / 2)';
$TX = '((' . $TR . ' - ' . $TH . ') / ' . $TR . ')';
$TACOS = '(2 * atan(sqrt((1 - ' . $TX . ') / max(1 + ' . $TX . ', 1e-12))))';
$TAREA = '(' . $TR . ' * ' . $TR . ' * ' . $TACOS . ' - (' . $TR . ' - ' . $TH . ') * sqrt(max(2 * ' . $TR . ' * ' . $TH . ' - ' . $TH . ' * ' . $TH . ', 0)))';
$TVOL = '(' . $TAREA . ' * v.len / 1000)';
$TFULL = '(PI * ' . $TR . ' * ' . $TR . ' * v.len / 1000)';

// Tyre diameter in mm
$D1 = '(v.r1 * 25.4 + 2 * v.w1 * v.a1 / 100)';
$D2 = '(v.r2 * 25.4 + 2 * v.w2 * v.a2 / 100)';

