       ['en' => 'Variation % of sales', 'gu' => 'વેચાણના % માં ઘટ-વધ', 'f' => 'v.sl ? (v.cl - (v.op + v.rc - v.sl)) / v.sl * 100 : 0', 'fmt' => 'pct', 'd' => 3],
