       ['en' => 'MOP (60% K₂O)', 'gu' => 'MOP પોટાશ (60% K₂O)', 'f' => 'v.k * ' . $HA . ' / 0.60', 'fmt' => 'num', 'd' => 1, 'u' => 'kg', 'u_gu' => 'કિલો'],
